package main

import (
	"context"
	"fmt"

	"example.com/lib"
)

// greeting wraps the library call so tests do not depend on its signature.
func greeting(name string) string {
	return lib.Greet(context.Background(), name)
}

func main() {
	fmt.Println(greeting("steward"))
}

package main

// Notes on the example.com/lib v1.3.0 upgrade: Greet now takes a context.
var upgradeNotes = "lib v1.3.0: Greet(ctx, name)"
